"use client";

import React from "react";
import { useEffect, useState } from "react";
import axios from "axios";
import { motion, AnimatePresence, Variants } from "framer-motion";
import { UserButton, useUser, SignOutButton, UserProfile } from "@clerk/nextjs";

// Existing components - keeping for functionality
import { CreditGauge } from "../../components/Loan";
import { useCreditStore } from "../../store/useCreditStore";
import LedgerSearchBox from "../ledger/LedgerSearchBox";
import { GlassPanel } from "../../components/ui/GlassPanel";
import StockReport from "../stock/StockReport";
import LedgerEntries from "../ledger/LedgerEntries";
import ProfitLossReport from "../stock/ProfitLossReoprt";
import StockValuation from "../stock/StockValuation";
import StockAlertSmart from "../Insights/StockAlert";
import CashFlowWatch from "../Insights/CashFlow";
import AlertsFeed from "../alerts/AlertsFeed";
import License_Report from "../loan_licenses/License_Report";
import BusinessHealthCard from "../health/BusinessHealthCard";
import SlowMovingStockContainer from "../Insights/SlowMovingStockContainer";
import { ActionSuggestionCard, ForecastSummaryCard, MarginTrendGraph, SalesTrendGraphCard, TopProductDonut } from "../Insights/SalesTrendInsightsCard";
import KPICards from "./KPICards";
import TopProductsCard from "../Insights/TopProductCard";
import Purchase from "../stock/Purchase";
import Sale from "../stock/Sale";
import { Toaster } from "react-hot-toast";
import { fetchDashboardData } from "@/src/lib/api/dashboard";


// Icons as inline SVGs
const Icons = {
  logo: (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
      <polyline points="22 7 13.5 15.5 8.5 10.5 2 17" />
      <polyline points="16 7 22 7 22 13" />
    </svg>
  ),
  overview: (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect x="3" y="3" width="7" height="7" rx="1" /><rect x="14" y="3" width="7" height="7" rx="1" /><rect x="14" y="14" width="7" height="7" rx="1" /><rect x="3" y="14" width="7" height="7" rx="1" />
    </svg>
  ),
  inventory: (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z" /><path d="m3.3 7 8.7 5 8.7-5" /><path d="M12 22V12" />
    </svg>
  ),
  finance: (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 3v18h18" /><path d="m19 9-5 5-4-4-3 3" />
    </svg>
  ),
  ledger: (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M4 19.5v-15A2.5 2.5 0 0 1 6.5 2H19a1 1 0 0 1 1 1v18a1 1 0 0 1-1 1H6.5a1 1 0 0 1 0-5H20" /><path d="M8 11h8" /><path d="M8 7h6" />
    </svg>
  ),
  loans: (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect width="20" height="14" x="2" y="5" rx="2" /><line x1="2" x2="22" y1="10" y2="10" />
    </svg>
  ),
  alerts: (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9" /><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0" />
    </svg>
  ),
  settings: (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.73l.15.1a2 2 0 0 1 1 1.72v.51a2 2 0 0 1-1 1.74l-.15.09a2 2 0 0 0-.73 2.73l.22.38a2 2 0 0 0 2.73.73l.15-.08a2 2 0 0 1 2 0l.43.25a2 2 0 0 1 1 1.73V20a2 2 0 0 0 2 2h.44a2 2 0 0 0 2-2v-.18a2 2 0 0 1 1-1.73l.43-.25a2 2 0 0 1 2 0l.15.08a2 2 0 0 0 2.73-.73l.22-.39a2 2 0 0 0-.73-2.73l-.15-.08a2 2 0 0 1-1-1.74v-.5a2 2 0 0 1 1-1.74l.15-.09a2 2 0 0 0 .73-2.73l-.22-.38a2 2 0 0 0-2.73-.73l-.15.08a2 2 0 0 1-2 0l-.43-.25a2 2 0 0 1-1-1.73V4a2 2 0 0 0-2-2z" /><circle cx="12" cy="12" r="3" />
    </svg>
  ),
  search: (
    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="11" cy="11" r="8" /><path d="m21 21-4.3-4.3" />
    </svg>
  ),
  chevronRight: (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="m9 18 6-6-6-6" />
    </svg>
  ),
  signOut: (
    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4" /><polyline points="16 17 21 12 16 7" /><line x1="21" x2="9" y1="12" y2="12" />
    </svg>
  ),
  menu: (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <line x1="4" x2="20" y1="12" y2="12" /><line x1="4" x2="20" y1="6" y2="6" /><line x1="4" x2="20" y1="18" y2="18" />
    </svg>
  ),
  close: (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M18 6 6 18" /><path d="m6 6 12 12" />
    </svg>
  ),
  calendar: (
    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M8 2v4" /><path d="M16 2v4" /><rect width="18" height="18" x="3" y="4" rx="2" /><path d="M3 10h18" />
    </svg>
  ),
  trash: (
    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 6h18" /><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6" /><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2" />
    </svg>
  ),
  features: (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" />
    </svg>
  ),
};


import ActiveLoans, { Loan } from "../loan_licenses/ActiveLoans";



// Animation variants
const fadeInUp: Variants = {
  hidden: {
    opacity: 0,
    y: 20,
  },
  visible: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.4,
      ease: "easeOut",
    },
  },
};

const staggerContainer: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.08 },
  },
};

// Navigation Items
const navItems = [
  { id: "overview", label: "Overview", icon: Icons.overview },
  { id: "inventory", label: "Inventory", icon: Icons.inventory },
  { id: "finance", label: "Finance", icon: Icons.finance },
  { id: "ledger", label: "Ledger", icon: Icons.ledger },
  { id: "loans", label: "Loans", icon: Icons.loans },
  { id: "alerts", label: "Alerts", icon: Icons.alerts },
  { id: "settings", label: "Settings", icon: Icons.settings },
];

const PanelMotion = ({ children }: { children: React.ReactNode }) => (
  <motion.div
    initial={{ opacity: 0, y: 24 }}
    animate={{ opacity: 1, y: 0 }}
    exit={{ opacity: 0, y: 12 }}
    transition={{ duration: 0.35, ease: "easeOut" }}
  >
    {children}
  </motion.div>
);


export default function Dashboard() {
  const { user } = useUser();
  const email = user?.primaryEmailAddress?.emailAddress;
  const { score, show } = useCreditStore();

  const [loans, setLoans] = useState<Loan[]>([]);
  const [loadingLoans, setLoadingLoans] = useState(true);
  const [activeSection, setActiveSection] = useState("overview");
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [newPurchase, setNewPurchase] = useState(false);
  const [newSale, setNewSale] = useState(false);
  const [reload, setReload] = useState(false);
  const [product, setProduct] = useState("");
  const [searchQuery, setSearchQuery] = useState("");

  const [dashboardData, setDashboardData] = useState<any>(null);
  const [loadingDashboard, setLoadingDashboard] = useState(true);


  const [data, setData] = useState<any | null>(null);
  const [loadingInsights, setLoadingInsights] = useState(true);


  useEffect(() => {
    if (!email) return;

    const load = async () => {
      setLoadingDashboard(true);
      try {
        const data = await fetchDashboardData(email);
        setDashboardData(data);
        setLoans(data.loans);
        setData(data.salesTrend7);
      } catch (err) {
        console.error(err);
      } finally {
        setLoadingDashboard(false);
        setLoadingInsights(false);
        setLoadingLoans(false);
      }
    };

    load();
  }, [email, reload]);


  const scrollToSection = (id: string) => {
    setActiveSection(id);
    setSidebarOpen(false);
  };




  // Section titles and subtitles
  const sectionInfo: Record<string, { title: string; subtitle: string }> = {
    overview: { title: "Business Overview", subtitle: "High-level snapshot of your business" },
    inventory: { title: "Inventory", subtitle: "Stock levels, valuation & alerts" },
    finance: { title: "Finance", subtitle: "Profitability & cash movement" },
    ledger: { title: "Ledger", subtitle: "Purchase & sales history" },
    loans: { title: "Loans & Licenses", subtitle: "Active loans & lending profile" },
    alerts: { title: "Alerts & Insights", subtitle: "System-generated recommendations" },
    settings: { title: "Settings", subtitle: "Manage your account preferences" },
  };

  const card =
    "glass-panel transition-all hover:border-white/20";

  return (
    <div className="min-h-screen bg-background flex">
      <Toaster />

      {/* Mobile Header */}
      <header className={`lg:hidden fixed top-0 left-0 right-0 z-50 ${card}`}>
        <div className="flex items-center justify-between px-4 py-3">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-xl bg-primary/20 flex items-center justify-center text-primary">
              {Icons.logo}
            </div>
            <span className="font-semibold text-foreground">Solicio</span>
          </div>
          <button
            onClick={() => setSidebarOpen(!sidebarOpen)}
            className="p-2 rounded-lg hover:bg-white/10 text-muted transition-colors"
          >
            {sidebarOpen ? Icons.close : Icons.menu}
          </button>
        </div>
      </header>

      {/* Mobile Sidebar Overlay */}
      <AnimatePresence>
        {sidebarOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setSidebarOpen(false)}
            className="lg:hidden fixed inset-0 z-40 bg-black/30"
          />
        )}
      </AnimatePresence>

      {/* Sidebar */}
      <aside
        className={`fixed top-0 left-0 z-50 h-full w-[280px] ${card} flex flex-col
          transform transition-transform duration-300 ease-out
          ${sidebarOpen ? "translate-x-0" : "-translate-x-full"}
          lg:translate-x-0 lg:z-30`}
      >
        {/* Sidebar Header */}
        <div className="p-6">
          <div className="flex items-center gap-3">
            <motion.div
              whileHover={{ scale: 1.05 }}
              className="w-11 h-11 rounded-xl bg-gradient-to-br from-emerald-500 to-emerald-600 text-white"
            >
              {Icons.logo}
            </motion.div>
            <div>
              <h1 className="font-bold text-foreground text-lg">Solicio</h1>
              <p className="text-xs text-muted">Business Dashboard</p>
            </div>
          </div>
        </div>

        {/* Navigation */}
        <nav className="flex-1 px-4">
          <p className="px-3 mb-3 text-xs font-semibold text-white/40 uppercase tracking-wider">Menu</p>
          <div className="space-y-1">
            <motion.a
              href="/"
              className="w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all duration-200 text-muted hover:bg-white/5"
              whileHover={{ x: 2 }}
              whileTap={{ scale: 0.98 }}
            >
              <div className="flex items-center gap-3">
                <span className="text-base">🏚️</span>
                <span className="font-medium text-sm">Home</span>
              </div>
            </motion.a>
            <motion.a
              href="/features"
              className="w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all duration-200 text-muted hover:bg-white/5"
              whileHover={{ x: 2 }}
              whileTap={{ scale: 0.98 }}
            >
              <div className="flex items-center gap-3">
                <span className="text-stone-500">{Icons.features}</span>
                <span className="font-medium text-sm">Features</span>
              </div>
            </motion.a>
            {navItems.map((item) => (
              <motion.button
                key={item.id}
                onClick={() => scrollToSection(item.id)}
                whileHover={{ x: activeSection === item.id ? 0 : 2 }}
                whileTap={{ scale: 0.98 }}
                className={`w-full flex items-center justify-between px-4 py-3 rounded-xl text-left transition-all duration-200
                  ${activeSection === item.id
                    ? "bg-primary text-background shadow-lg shadow-primary/20"
                    : "text-muted hover:bg-white/5"
                  }`}
              >
                <div className="flex items-center gap-3">
                  <span className={activeSection === item.id ? "text-background" : "text-white/50"}>
                    {item.icon}
                  </span>
                  <span className="font-medium text-sm">{item.label}</span>
                </div>
                {activeSection === item.id && (
                  <motion.span
                    initial={{ opacity: 0, x: -5 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="text-background"
                  >
                    {Icons.chevronRight}
                  </motion.span>
                )}
              </motion.button>
            ))}
          </div>
        </nav>

        {/* User Section */}
        <div className={`p-4 ${card} !bg-transparent !border-0`}>
          <div className="flex items-center gap-3 p-3 rounded-xl bg-white/5 border border-white/5">
            <div className="w-10 h-10 rounded-full bg-emerald-100 flex items-center justify-center text-emerald-700 font-semibold">
              {user?.firstName?.charAt(0) || "U"}
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-semibold text-foreground truncate">
                {user?.fullName || "User"}
              </p>
              <p className="text-xs text-muted truncate">{email}</p>
            </div>
          </div>
          <SignOutButton>
            <button className="w-full mt-3 flex items-center gap-3 px-4 py-2.5 text-muted hover:text-white hover:bg-white/5 rounded-xl transition-colors">
              {Icons.signOut}
              <span className="text-sm font-medium">Sign out</span>
            </button>
          </SignOutButton>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 lg:ml-[280px] min-h-screen pt-16 lg:pt-0">
        {/* Top Header Bar */}
        <div className="p-6 w-13/14 place-self-center">
          {email && <LedgerSearchBox key={activeSection} email={email} />}
        </div>

        {/* Page Content */}
        <div className="max-w-6xl mx-auto px-6 py-8">
          {/* Page Title */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="mb-8"
          >
            <h1 className="text-2xl font-bold text-foreground tracking-tight">
              {sectionInfo[activeSection]?.title || "Dashboard"}
            </h1>
            <p className="text-muted mt-1">
              {sectionInfo[activeSection]?.subtitle || "Manage your business"}
            </p>
          </motion.div>

          {/* Sections */}
          <div className="space-y-8">
            {/* OVERVIEW SECTION */}
            {activeSection === "overview" && (
              <section id="overview">
                <motion.div
                  variants={staggerContainer}
                  initial="hidden"
                  animate="visible"
                  className="space-y-6"
                >
                  {/* Business Health Card */}
                  <GlassPanel className="p-6">
                    <div className="pb-6">
                      <KPICards data={dashboardData?.kpis} />
                    </div>
                    {email && <BusinessHealthCard data={dashboardData?.healthSummary} />}
                  </GlassPanel>

                  {/* Two Column Layout */}
                  <div className="grid md:grid-cols-2 gap-6">
                    {(
                      <GlassPanel className="p-6">
                        <CreditGauge score={score} />
                      </GlassPanel>
                    )}
                    <GlassPanel className="p-6">
                      <CashFlowWatch data={dashboardData?.cashFlow} />
                    </GlassPanel>
                  </div>
                  {loadingInsights ? (
                    <GlassPanel className="p-10 flex items-center justify-center">
                      <motion.div
                        animate={{ rotate: 360 }}
                        transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                        className="w-8 h-8 border-2 border-primary/20 border-t-primary rounded-full"
                      />
                    </GlassPanel>
                  ) : !data ? (
                    <div className="bg-white rounded-2xl p-10 text-center text-stone-500">
                      Unable to load insights
                    </div>
                  ) : (
                    <section className="mx-auto max-w-7xl px-4 py-20 space-y-10">
                      {/* 1️⃣ Sales Trend (hero insight) */}
                      <SalesTrendGraphCard data={data} />

                      {/* 2️⃣ Forward-looking */}
                      <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                        <ForecastSummaryCard data={data} />
                      </div>

                      {/* 4️⃣ Context */}
                      <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                        <TopProductDonut data={data} />
                        <MarginTrendGraph data={data} />
                      </div>

                      {/* 5️⃣ Advice */}
                      <ActionSuggestionCard data={data} />
                    </section>
                  )}

                </motion.div>
              </section>
            )}

            {/* INVENTORY SECTION */}
            {activeSection === "inventory" && (
              <section id="inventory">
                <motion.div
                  variants={staggerContainer}
                  initial="hidden"
                  whileInView="visible"
                  viewport={{ once: true }}
                  className="space-y-6"
                >
                  <GlassPanel className="p-6">
                    <StockReport
                      visible={true}
                      data={dashboardData?.inventory}
                      productSetter={setProduct}
                      saleSetter={setNewSale}
                      purchaseSetter={setNewPurchase}
                    />
                  </GlassPanel>

                  {/* FORMS */}
                  <AnimatePresence mode="wait">
                    {newPurchase && (
                      <PanelMotion key="purchase">
                        <Purchase
                          visible={true}
                          preSelectedProduct={product}
                          reloadSetter={setReload}
                          reload={reload}
                        />
                      </PanelMotion>
                    )}

                    {newSale && (
                      <PanelMotion key="sale">
                        <Sale
                          visible={true}
                          preSelectedProduct={product}
                          reloadSetter={setReload}
                          reload={reload}
                        />
                      </PanelMotion>
                    )}
                  </AnimatePresence>
                  <GlassPanel className="p-6">
                  </GlassPanel>
                  <GlassPanel className="p-6">
                    <StockAlertSmart data={dashboardData?.lowStock} />
                  </GlassPanel>
                  <GlassPanel className="p-6">
                    <StockValuation />
                  </GlassPanel>
                </motion.div>
              </section>
            )}

            {/* FINANCE SECTION */}
            {activeSection === "finance" && (
              <section id="finance">
                <motion.div
                  variants={staggerContainer}
                  initial="hidden"
                  whileInView="visible"
                  viewport={{ once: true }}
                  className="space-y-6"
                >
                  <GlassPanel className="p-6">
                    <ProfitLossReport />
                  </GlassPanel>
                  <GlassPanel className="p-6">
                    <CashFlowWatch data={dashboardData?.cashFlow} />
                  </GlassPanel>
                </motion.div>
              </section>
            )}

            {/* LEDGER SECTION */}
            {activeSection === "ledger" && (
              <section id="ledger">
                <motion.div
                  variants={staggerContainer}
                  initial="hidden"
                  whileInView="visible"
                  viewport={{ once: true }}
                  className="space-y-6"
                >
                  <GlassPanel className="p-6">
                    <LedgerEntries />
                  </GlassPanel>

                </motion.div>
              </section>
            )}

            {/* LOANS SECTION */}
            {activeSection === "loans" && (
              <section id="loans">
                <motion.div
                  variants={staggerContainer}
                  initial="hidden"
                  whileInView="visible"
                  viewport={{ once: true }}
                  className="space-y-6"
                >
                  <ActiveLoans data={loans} loading={loadingLoans} setLoans={setLoans} />

                  {/* Licenses */}
                  <GlassPanel className="p-6">
                    <License_Report />
                  </GlassPanel>
                </motion.div>
              </section>
            )}

            {/* ALERTS & INSIGHTS SECTION */}
            {activeSection === "alerts" && (
              <section id="alerts">
                <motion.div
                  variants={staggerContainer}
                  initial="hidden"
                  whileInView="visible"
                  viewport={{ once: true }}
                  className="space-y-6"
                >
                  <GlassPanel className="p-6">
                    <SlowMovingStockContainer data={dashboardData?.slowMoving} />
                  </GlassPanel>
                  <GlassPanel className="p-6">
                    {email && <AlertsFeed email={email} />}
                  </GlassPanel>
                </motion.div>
              </section>
            )}

            {/* SETTINGS SECTION */}
            {activeSection === "settings" && (
              <section id="settings">
                <motion.div
                  variants={fadeInUp}
                  initial="hidden"
                  whileInView="visible"
                  viewport={{ once: true }}
                  className="glass-panel p-6"
                >
                  <UserProfile routing="hash" />
                </motion.div>
              </section>
            )}
          </div>

          {/* Footer Spacer */}
          <div className="h-8" />
        </div >
      </main >
    </div >
  );
}
