"use client";

import {
  DollarSign,
  TrendingUp,
  Package,
  ShoppingCart,
} from "lucide-react";
import { GlassPanel } from "../../components/ui/GlassPanel";

function Card({
  icon: Icon,
  title,
  value,
  pct,
  iconBg,
  iconColor,
}: any) {
  const up = pct >= 0;

  return (
    <GlassPanel className="p-6 hover:border-emerald-500/30 transition-all duration-300 group">
      <div className="flex justify-between items-start">
        <div
          className={`h-12 w-12 rounded-xl flex items-center justify-center ${iconBg} bg-opacity-10 backdrop-blur-sm`}
        >
          <Icon size={22} className={iconColor} />
        </div>

        <span
          className={`text-xs font-bold px-2 py-1 rounded-full flex items-center gap-1 border ${up
            ? "text-emerald-400 bg-emerald-500/10 border-emerald-500/20"
            : "text-rose-400 bg-rose-500/10 border-rose-500/20"
            }`}
        >
          {up ? "↑" : "↓"} {Math.abs(pct)}%
        </span>
      </div>

      <p className="mt-4 text-sm text-white/50">{title}</p>

      <p className="mt-1 text-3xl font-bold text-white tracking-tight">
        {value}
      </p>
    </GlassPanel>
  );
}

export default function KPICards({ data }: { data: any }) {
  if (!data) return null;

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
      <Card
        icon={DollarSign}
        title="Total Revenue"
        value={`₹${data.revenue.value.toLocaleString()}`}
        pct={data.revenue.pct}
        iconBg="bg-indigo-100"
        iconColor="text-indigo-600"
      />

      <Card
        icon={TrendingUp}
        title="Net Profit"
        value={`₹${data.profit.value.toLocaleString()}`}
        pct={data.profit.pct}
        iconBg="bg-emerald-100"
        iconColor="text-emerald-600"
      />

      <Card
        icon={Package}
        title="Total Inventory"
        value={data.inventory.value}
        pct={data.inventory.pct}
        iconBg="bg-violet-100"
        iconColor="text-violet-600"
      />

      <Card
        icon={ShoppingCart}
        title="Total Orders"
        value={data.orders.value}
        pct={data.orders.pct}
        iconBg="bg-orange-100"
        iconColor="text-orange-600"
      />
    </div>
  );
}
